// Both stores in one list: the 1-2★ reviews that no previous run has seen (workflow static data).
const MAX_KEYS = 5000;                       // store|review_id keys remembered between runs (oldest dropped)
const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];
const seen = new Set(store.seen);
const rowsOf = (node) => { try { return $(node).all().map(i => i.json); } catch (e) { return []; } };   // a disabled branch just returns nothing
const appStore = rowsOf('Run App Store reviews');
const play = rowsOf('Run Google Play reviews');
const names = {};
for (const r of [...appStore, ...play]) if (r.type === 'app' && r.app_name) names[String(r.app_id)] = r.app_name;
const clip = (s, n) => { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const all = [
  // App Store rows: numeric app_id, a `title` above the text, the app version in `version`, storefront in `country`.
  ...appStore.filter(r => r.type === 'review' && r.review_id).map(r => ({
    store: 'App Store', app_id: String(r.app_id), app_name: r.app_name || names[String(r.app_id)] || String(r.app_id),
    review_id: String(r.review_id), rating: r.rating, title: r.title || '', text: clip(r.text, 400),
    author: r.author || '', version: r.version || 'n/a', country: String(r.country || '').toUpperCase(), language: '',
    review_date: String(r.review_date || '').slice(0, 10), developer_reply: r.developer_response || '', url: r.url || '',
  })),
  // Google Play rows: package name as app_id, no title, the app version in `app_version`, a `language` beside the country.
  ...play.filter(r => r.type === 'review' && r.review_id).map(r => ({
    store: 'Google Play', app_id: String(r.app_id), app_name: r.app_name || names[String(r.app_id)] || String(r.app_id),
    review_id: String(r.review_id), rating: r.rating, title: '', text: clip(r.text, 400),
    author: r.author || '', version: r.app_version || 'n/a', country: String(r.country || '').toUpperCase(), language: r.language || '',
    review_date: String(r.review_date || '').slice(0, 10), developer_reply: r.reply_text || '', url: r.url || '',
  })),
];
const fresh = all.filter(r => !seen.has(`${r.store}|${r.review_id}`));
fresh.sort((a, b) => (a.rating - b.rating) || String(b.review_date).localeCompare(String(a.review_date)));
for (const r of fresh) store.seen.push(`${r.store}|${r.review_id}`);
if (store.seen.length > MAX_KEYS) store.seen = store.seen.slice(-MAX_KEYS);
if (!fresh.length) return [{ json: { none: true, reviews_received: all.length, app_store: appStore.filter(r => r.type === 'review').length, google_play: play.filter(r => r.type === 'review').length, ids_remembered: store.seen.length } }];
return fresh.map(json => ({ json }));
